The event handlers for the adorner events are pretty straight forward (yes, yes it creates a new LinearGradientBrush every time, that can and should be optimized out) :
void slider_ValueChanged(object sender, RoutedPropertyChangedEventArgs<double> e) { UIElement adornedControl = AdornerPanel.GetAdornedElement((UIElement)sender); SliderAdornedButton button = adornedControl as SliderAdornedButton; if (button != null) { LinearGradientBrush gradBrush = new LinearGradientBrush(); gradBrush.StartPoint = new Point(0, 0); gradBrush.EndPoint = new Point(1, 1); gradBrush.GradientStops.Add(new GradientStop(Colors.Red, 0.0)); gradBrush.GradientStops.Add(new GradientStop(Colors.Yellow, e.NewValue)); gradBrush.GradientStops.Add(new GradientStop(Colors.Green, 1));
button.Background = gradBrush; } }
